    await cli("add", "--title", "Other", "--tags", "beta", "--due", "2020-01-01");
    expect((await cli("list", "--tag", "ALPHA", "--status", "open", "--overdue", "2020-01-02")).json.map((task: any) => task.id)).toEqual([1]);
  });

